        alg_271_JIPR_9 = kIPR_9 * (P_10 * alg_265_phi1_9 * H_9 / (P_10 * alg_265_phi1_9 + alg_268_phi_1_9)) ** 4.0 * (CER_9 - CS2_9)
        d_CS2_9 = torch.zeros_like(y[:, 0]) + (alg_43_JS2Cy9 + lambda_ER_S2_9 * alg_271_JIPR_9 - (lambda_S1_S2_9 * alg_54_JS1S2_9 + lambda_MT_S2_9 * alg_263_JMCU_9))
        d_CER_9 = torch.zeros_like(y[:, 0]) + (alg_259_JSERCA_9 - alg_271_JIPR_9)
