        d_H_9 = torch.zeros_like(y[:, 0]) + (alg_274_phi3_9 * (1.0 - H_9) - P_10 * alg_265_phi1_9 * alg_272_phi2_9 / (P_10 * alg_265_phi1_9 + alg_268_phi_1_9) * H_9)
        alg_275_ENa_PU_10 = R_11 * T_11 / F_11 * torch.log(NO_11 / NS1_10)
        alg_276_I_Na_11 = gNa_10 * (Vm - alg_275_ENa_PU_10)
        alg_283_I_NaP_10 = gNaP_10 * (NS1_10 ** hNaP_10 / (KNaP_10 ** hNaP_10 + NS1_10 ** hNaP_10)) * (ENaP_10 - Vm)
        alg_279_gNSCC_Na_10 = gNSCC_Na_10 * (KNSCC_10 ** hNSCC_10 / (KNSCC_10 ** hNSCC_10 + CS1_10 ** hNSCC_10))
        alg_280_I_NSCC_Na_10 = alg_279_gNSCC_Na_10 * (Vm - ENSCC_10)
        alg_285_I_iNa_10 = alpha_scale_10 * (alg_280_I_NSCC_Na_10 + alg_276_I_Na_11 + alg_283_I_NaP_10)
        d_NS1_10 = torch.zeros_like(y[:, 0]) + (-(delta_SPU_10 / (1.0 * alpha_scale_10)) * alg_285_I_iNa_10)
        alg_29_I_Kv1_1 = g_Kv1_1 * dv1_1 * fv1_1 * (Vm - EK)
        alg_30_I_KERG = g_KERG * dERG * (Vm - EK)
        alg_31_I_KB = g_KB * (Vm - EK)
        alg_32_I_Na = g_Na * dNa * fNa * (Vm - ENa_Cy)
        alg_33_I_L = g_L * (Vm - EL)
        alg_34_I_ion_Cy = alg_7_I_CaT + alg_25_I_CaExt + alg_29_I_Kv1_1 + alg_30_I_KERG + alg_31_I_KB + alg_32_I_Na + alg_33_I_L
        alg_72_I_ion_PU = alg_66_I_iCa + alg_70_I_iNa
        alg_96_I_ion_PU_2 = alg_90_I_iCa_2 + alg_94_I_iNa_2
        alg_120_I_ion_PU_3 = alg_114_I_iCa_3 + alg_118_I_iNa_3
