        alg_264_I_ion_PU_9 = alg_258_I_iCa_9 + alg_262_I_iNa_9
        alg_267_gCa_10 = gCa_10 * torch.exp(kCa_10 * Vm) / (1.0 + torch.exp(kVCa_10 * (Vm - VhCa_10)))
        alg_270_ECa_PU_10 = R_11 * T_11 / (2.0 * F_11) * torch.log(CO_11 / CS1_10)
        alg_273_I_Ca_10 = alg_267_gCa_10 * (Vm - alg_270_ECa_PU_10)
