        alg_287_I_ion_PU_10 = alg_282_I_iCa_10 + alg_285_I_iNa_10
        d_Vm = torch.zeros_like(y[:, 0]) + (-(1.0 / Cm) * (alg_34_I_ion_Cy + alg_72_I_ion_PU + alg_96_I_ion_PU_2 + alg_120_I_ion_PU_3 + alg_144_I_ion_PU_4 + alg_168_I_ion_PU_5 + alg_192_I_ion_PU_6 + alg_216_I_ion_PU_7 + alg_240_I_ion_PU_8 + alg_264_I_ion_PU_9 + alg_287_I_ion_PU_10))
        alg_55_JS1S2_10 = mu_S1S2_10 * (CS2_10 - CS1_10)
        alg_284_JSERCA_10 = VSERCA_10 * (CS1_10 - A2_10 * CER_10) / (1.0 + A4_10 * CS1_10 + A5_10 * CER_10 + A6_10 * CS1_10 * CER_10)
        alg_290_JNCX_10 = VNCX_10 * (CMT_10 / (CMT_10 + KNCX_10))
        d_CS1_10 = torch.zeros_like(y[:, 0]) + (alg_55_JS1S2_10 + lambda_MT_S1_10 * alg_290_JNCX_10 - (delta_SPU_10 / (alpha_scale_10 * 2.0) * alg_282_I_iCa_10 + lambda_ER_S1_10 * alg_284_JSERCA_10))
