        alg_288_JMCU_10 = VMCU_10 * (CS2_10 ** 2.0 / (KMCU_10 ** 2.0 + CS2_10 ** 2.0)) * alg_286_epsilon_INH_10
        alg_292_fm_10 = 1.0 / (1.0 + Km_10 * Bm_10 / (Km_10 + CMT_10) ** 2.0)
        d_CMT_10 = torch.zeros_like(y[:, 0]) + (alg_292_fm_10 * (alg_288_JMCU_10 - alg_290_JNCX_10))
