        d_CS2_10 = torch.zeros_like(y[:, 0]) + (alg_44_JS2Cy10 + lambda_ER_S2_10 * alg_293_JIPR_10 - (lambda_S1_S2_10 * alg_55_JS1S2_10 + lambda_MT_S2_10 * alg_288_JMCU_10))
